+ const load = (): Promise<AutomaticSpeechRecognitionPipeline> => {
+   listener ??= pipeline('automatic-speech-recognition', LISTEN_MODEL, {
+     dtype: { encoder_model: 'q8', decoder_model_merged: 'q8' },
+     device: 'wasm',
